script:
(function() {
  const trainer = frappe.session.user;
  const root = root_element;

  // State
  let currentPage = 1;
  const pageSize = 20;
  let totalRecords = 0;
  let searchText = "";
  let dateFrom = null;
  let dateTo = null;
  let currentOffset = 0;

  const greetingDiv = root.querySelector(".aad-greeting");
  const userFullName = frappe.user_info(frappe.session.user).fullname || frappe.session.user;

  const filterToggleBtn = root.querySelector(".aad-filter-toggle-btn");
  const filterDropdownPanel = root.querySelector(".aad-filter-dropdown-panel");

  filterToggleBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    const isVisible = filterDropdownPanel.style.display === "block";
    filterDropdownPanel.style.display = isVisible ? "none" : "block";
  });

  document.addEventListener("click", () => {
    if (filterDropdownPanel.style.display === "block") {
      filterDropdownPanel.style.display = "none";
    }
  });

  filterDropdownPanel.addEventListener("click", (e) => e.stopPropagation());

  if (greetingDiv) {
    greetingDiv.textContent = `Hello ${userFullName}`;
  }

  function getFirstDayOfMonth() {
    const date = new Date();
    return new Date(date.getFullYear(), date.getMonth(), 1);
  }

  function formatDateAPI(date) {
    const d = new Date(date);
    const month = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    return `${d.getFullYear()}-${month}-${day}`;
  }

  function formatDateDisplay(dateStr) {
    if (!dateStr) return "";
    const [year, month, day] = dateStr.split("-");
    return `${day}/${month}/${year}`;
  }

  function formatDateLongWithOrdinal(dateStr) {
    if (!dateStr) return "";
    const date = new Date(dateStr);
    if (isNaN(date)) return "";

    const day = date.getDate();
    const month = date.toLocaleString(undefined, { month: "long" });
    const year = date.getFullYear();
    const ordinal = getOrdinalSuffix(day);

    return `${day}${ordinal} ${month} ${year}`;
  }

  function getOrdinalSuffix(day) {
    if (day > 3 && day < 21) return "th";
    switch (day % 10) {
      case 1: return "st";
      case 2: return "nd";
      case 3: return "rd";
      default: return "th";
    }
  }

  function updateDateSummary() {
    const summaryDiv = root.querySelector(".aad-date-summary");
    if (!summaryDiv) return;
    const fromText = formatDateLongWithOrdinal(dateFrom);
    const toText = formatDateLongWithOrdinal(dateTo);

    if (fromText && toText) {
      summaryDiv.textContent = `Showing results from date ${fromText} to date ${toText}`;
    } else if (fromText) {
      summaryDiv.textContent = `Showing results from date ${fromText}`;
    } else if (toText) {
      summaryDiv.textContent = `Showing results up to date ${toText}`;
    } else {
      summaryDiv.textContent = "";
    }
  }

  function initializeDates() {
    const today = new Date();
    const firstDay = getFirstDayOfMonth();

    dateFrom = formatDateAPI(firstDay);
    dateTo = formatDateAPI(today);

    root.querySelector(".aad-date-from").value = dateFrom;
    root.querySelector(".aad-date-to").value = dateTo;

    updateDateSummary();

    root.querySelector(".aad-date-from").addEventListener("change", (e) => {
      dateFrom = e.target.value;
      currentPage = 1;
      loadData();
      updateDateSummary();
    });

    root.querySelector(".aad-date-to").addEventListener("change", (e) => {
      dateTo = e.target.value;
      currentPage = 1;
      loadData();
      updateDateSummary();
    });

    loadData()
  }

  function getFilters(search = "") {
    const filters = { trainer: trainer };

    if (dateFrom && dateTo) {
      filters["calling_date"] = ["between", [dateFrom, dateTo]];
    } else if (dateFrom) {
      filters["calling_date"] = [">=", dateFrom];
    } else if (dateTo) {
      filters["calling_date"] = ["<=", dateTo];
    }

    if (search) {
      filters["agent"] = ["like", `%${search}%`];
    }

    return filters;
  }

  function getStatusLabel(log) {
    if (log.wants_to_stay) {
      return "Wants to Stay";
    } else if (log.want_to_exit) {
      return "Want to Exit";
    } else if (log.exited) {
      return "Exited";
    } else {
      return "Pending";
    }
  }

  function getStatusInfo(log) {
    if (log.wants_to_stay) {
      return { label: "Wants to Stay", color: "green", indicator: "green" };
    } else if (log.want_to_exit) {
      return { label: "Want to Exit", color: "red", indicator: "red" };
    } else if (log.exited) {
      return { label: "Exited", color: "orange", indicator: "orange" };
    } else {
      return { label: "Pending", color: "gray", indicator: "gray" };
    }
  }

  // Helper to get plain text from HTML
  function stripHtmlTags(html) {
    if (!html) return "";
    const tmp = document.createElement("div");
    tmp.innerHTML = html;
    return tmp.textContent || tmp.innerText || "";
  }

  async function fetchTotalCount(filters = {}) {
    try {
      const result = await frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Agent Activation Call Log", filters: filters }
      });
      return result.message || 0;
    } catch (error) {
      console.error("Error fetching count:", error);
      return 0;
    }
  }

  async function fetchAnalytics() {
    try {
      const baseFilters = getFilters();

      const total = await fetchTotalCount(baseFilters);
      const stay = await fetchTotalCount({ ...baseFilters, wants_to_stay: 1 });
      const exit = await fetchTotalCount({ ...baseFilters, want_to_exit: 1 });
      const exited = await fetchTotalCount({ ...baseFilters, exited: 1 });

      root.querySelector(".aad-total-count").textContent = total;
      root.querySelector(".aad-stay-count").textContent = stay;
      root.querySelector(".aad-exit-count").textContent = exit;
      root.querySelector(".aad-exited-count").textContent = exited;

      totalRecords = total;
    } catch (error) {
      console.error("Error fetching analytics:", error);
    }
  }

  async function fetchLogs(page = 1, search = "") {
    try {
      const filters = getFilters(search);
      const offset = (page - 1) * pageSize;
      currentOffset = offset;

      const logs = await frappe.db.get_list("Agent Activation Call Log", {
        fields: [
          "name",
          "trainer",
          "report_date",
          "calling_date",
          "agent_phone_number",
          "agent",
          "date_of_joining",
          "connected_status",
          "reply_type",
          "wants_to_stay",
          "want_to_exit",
          "exited",
          "remarks",
          "modified"
        ],
        filters: filters,
        order_by: "modified desc",
        limit_page_length: pageSize,
        limit_start: offset
      });

      return logs;
    } catch (error) {
      console.error("Error fetching logs:", error);
      return [];
    }
  }

  async function fetchAllLogsForExport(search = "") {
    try {
      const filters = getFilters(search);

      const logs = await frappe.db.get_list("Agent Activation Call Log", {
        fields: [
          "name",
          "trainer",
          "report_date",
          "calling_date",
          "agent_phone_number",
          "agent",
          "date_of_joining",
          "connected_status",
          "reply_type",
          "wants_to_stay",
          "want_to_exit",
          "exited",
          "remarks",
          "modified"
        ],
        filters: filters,
        order_by: "modified desc",
        limit_page_length: 500
      });

      return logs;
    } catch (error) {
      console.error("Error fetching logs for export:", error);
      return [];
    }
  }

  function convertToCSV(logs) {
    const headers = [
      "#",
      "Log ID",
      "Trainer",
      "Report Date",
      "Calling Date",
      "Agent Phone Number",
      "Agent",
      "Date of Joining",
      "Connected Status",
      "Reply Type",
      "Wants to Stay",
      "Want to Exit",
      "Exited",
      "Remarks",
      "Modified"
    ];
    const rows = [];

    logs.forEach((log, index) => {
      const reportDate = log.report_date ? frappe.datetime.str_to_user(log.report_date) : "-";
      const callingDate = log.calling_date ? frappe.datetime.str_to_user(log.calling_date) : "-";
      const dateOfJoining = log.date_of_joining ? frappe.datetime.str_to_user(log.date_of_joining) : "-";
      const modifiedDate = log.modified ? frappe.datetime.str_to_user(log.modified) : "-";

      rows.push([
        index + 1,
        log.name,
        log.trainer || "-",
        reportDate,
        callingDate,
        log.agent_phone_number || "-",
        log.agent || "-",
        dateOfJoining,
        log.connected_status || "-",
        log.reply_type || "-",
        log.wants_to_stay ? "Yes" : "No",
        log.want_to_exit ? "Yes" : "No",
        log.exited ? "Yes" : "No",
        stripHtmlTags(log.remarks) || "-",
        modifiedDate
      ]);
    });

    let csvContent = headers.map(header => `"${header}"`).join(",") + "\n";
    rows.forEach(row => {
      csvContent += row.map(cell => `"${cell}"`).join(",") + "\n";
    });

    return csvContent;
  }

  async function downloadCSV() {
    try {
      const downloadBtn = root.querySelector(".aad-download-btn");
      const originalText = downloadBtn.innerHTML;

      downloadBtn.disabled = true;
      downloadBtn.innerHTML = '<span>⌛</span> Preparing...';

      const logs = await fetchAllLogsForExport(searchText);

      if (logs.length === 0) {
        frappe.msgprint("No records found to export");
        downloadBtn.disabled = false;
        downloadBtn.innerHTML = originalText;
        return;
      }

      const csvContent = convertToCSV(logs);

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      const url = URL.createObjectURL(blob);

      const today = new Date();
      const dateStr = today.toISOString().split("T")[0];
      const filename = `agent-activation-logs-${dateStr}.csv`;

      link.setAttribute("href", url);
      link.setAttribute("download", filename);
      link.style.visibility = "hidden";

      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      downloadBtn.disabled = false;
      downloadBtn.innerHTML = originalText;

      frappe.msgprint(`Downloaded ${logs.length} records`);
    } catch (error) {
      console.error("Error downloading CSV:", error);
      frappe.msgprint({
        title: "Error",
        indicator: "red",
        message: "Failed to download CSV file"
      });

      const downloadBtn = root.querySelector(".aad-download-btn");
      downloadBtn.disabled = false;
      downloadBtn.innerHTML = '<span>⬇</span> Download CSV';
    }
  }

  function renderTable(logs) {
    const tbody = root.querySelector(".aad-table-body");
    tbody.innerHTML = "";

    if (logs.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="6" class="aad-empty-state">
            <p>No records found</p>
          </td>
        </tr>
      `;
      return;
    }

    logs.forEach((log, index) => {
      const tr = document.createElement("tr");
      const rowNumber = currentOffset + index + 1;

      const callingDate = log.calling_date ? frappe.datetime.str_to_user(log.calling_date) : "-";
      const modifiedDate = log.modified ? frappe.datetime.prettyDate(log.modified) : "-";
      const statusInfo = getStatusInfo(log);

      tr.innerHTML = `
        <td class="aad-col-index aad-font-mono">${rowNumber}</td>
        <td>
          <a href="/app/agent-activation-call-log/${encodeURIComponent(log.name)}" class="aad-link">${frappe.utils.escape_html(log.name)}</a>
        </td>
        <td>${frappe.utils.escape_html(log.agent || "-")}</td>
        <td>${callingDate}</td>
        <td>
          <span class="aad-badge aad-badge-${statusInfo.indicator}">${statusInfo.label}</span>
        </td>
        <td>${modifiedDate}</td>
      `;

      tr.style.cursor = "pointer";
      tr.addEventListener("click", (e) => {
        if (e.target.tagName !== "A") {
          frappe.set_route("Form", "Agent Activation Call Log", log.name);
        }
      });

      tbody.appendChild(tr);
    });
  }

  function updatePagination() {
    const totalPages = Math.ceil(totalRecords / pageSize);
    const startRecord = totalRecords === 0 ? 0 : (currentPage - 1) * pageSize + 1;
    const endRecord = Math.min(currentPage * pageSize, totalRecords);

    root.querySelector(".aad-range-text").textContent = `Showing ${startRecord}-${endRecord} of ${totalRecords}`;

    root.querySelector(".aad-prev-btn").disabled = currentPage === 1;
    root.querySelector(".aad-next-btn").disabled = currentPage >= totalPages || totalRecords === 0;

    const pageContainer = root.querySelector(".aad-page-numbers");
    pageContainer.innerHTML = "";

    if (totalPages <= 1) return;

    let startPage = Math.max(1, currentPage - 2);
    let endPage = Math.min(totalPages, startPage + 4);

    if (endPage - startPage < 4) {
      startPage = Math.max(1, endPage - 4);
    }

    for (let i = startPage; i <= endPage; i++) {
      const btn = document.createElement("button");
      btn.classList.add("aad-btn", "aad-page-btn");
      if (i === currentPage) {
        btn.classList.add("aad-page-active");
      }
      btn.textContent = i;
      btn.addEventListener("click", () => goToPage(i));
      pageContainer.appendChild(btn);
    }
  }

  async function loadData() {
    const tbody = root.querySelector(".aad-table-body");
    tbody.innerHTML = `<tr class="aad-loading-row"><td colspan="6"><div class="aad-spinner"></div></td></tr>`;

    await fetchAnalytics();
    const logs = await fetchLogs(currentPage, searchText);
    renderTable(logs);
    updatePagination();
  }

  async function goToPage(page) {
    currentPage = page;
    await loadData();
  }

  function setupListeners() {
    root.querySelector(".aad-create-btn").addEventListener("click", () => {
      frappe.new_doc("Agent Activation Call Log");
    });

    root.querySelector(".aad-download-btn").addEventListener("click", () => {
      downloadCSV();
    });

    root.querySelector(".aad-date-from").addEventListener("change", (e) => {
      dateFrom = e.target.value;
      currentPage = 1;
      loadData();
      updateDateSummary();
    });

    root.querySelector(".aad-date-to").addEventListener("change", (e) => {
      dateTo = e.target.value;
      currentPage = 1;
      loadData();
      updateDateSummary();
    });

    root.querySelector(".aad-reset-filter").addEventListener("click", () => {
      initializeDates();
      currentPage = 1;
      searchText = "";
      root.querySelector(".aad-search").value = "";
      loadData();
      updateDateSummary();
    });

    const searchInput = root.querySelector(".aad-search");
    let searchTimer;
    searchInput.addEventListener("input", (e) => {
      clearTimeout(searchTimer);
      searchTimer = setTimeout(() => {
        searchText = e.target.value.trim();
        currentPage = 1;
        loadData();
      }, 300);
    });

    root.querySelector(".aad-prev-btn").addEventListener("click", () => {
      if (currentPage > 1) goToPage(currentPage - 1);
    });

    root.querySelector(".aad-next-btn").addEventListener("click", () => {
      const totalPages = Math.ceil(totalRecords / pageSize);
      if (currentPage < totalPages) goToPage(currentPage + 1);
    });
  }

  // Initialize
  initializeDates();
  setupListeners();
  updateDateSummary();
  loadData();

})();

style:
/* agent_activation_dashboard.css */



* {
  --text-muted: #6c7680;
  --text-base: #41464b;
  --text-dark: #1a1a1a;
  --border-subtle: #f0f0f0;
  --border-default: #d9d9d9;
  --bg-default: #fafbfc;
  --bg-secondary: #f8f9fa;
  --primary: #3b82f6;
  --primary-light: #dbeafe;
  --success: #10b981;
  --danger: #ef4444;
  --warning: #f59e0b;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}



.aad-dashboard {
  font-family: "Inter", "Segoe UI", Helvetica, Arial, sans-serif;
  color: var(--text-base);
  background: white;
  font-size: 13px;
  line-height: 1.5;
  padding: 0;
}

.aad-font-mono {
  font-family: "Monaco", "Menlo", "Ubuntu Mono", monospace;
  font-size: 12px;
}

/* Header */
.aad-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 24px;
  gap: 16px;
  flex-wrap: wrap;
}

.aad-title {
  margin: 0;
  font-size: 20px;
  font-weight: 600;
  color: var(--text-dark);
}

.aad-subtitle {
  margin: 4px 0 0 0;
  font-size: 12px;
  color: var(--text-muted);
}

.aad-header-actions {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}

/* Buttons */
.aad-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 6px;
  border: 1px solid var(--border-default);
  background: white;
  color: var(--text-base);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.aad-btn:hover:not(:disabled) {
  background: var(--bg-secondary);
  border-color: var(--border-default);
}

.aad-btn:active:not(:disabled) {
  transform: scale(0.98);
}

.aad-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.aad-btn-primary {
  background: var(--primary);
  color: white;
  border: none;
}

.aad-btn-primary:hover:not(:disabled) {
  background: #2563eb;
}

.aad-btn-secondary {
  background: white;
  border: 1px solid var(--border-default);
}

.aad-btn-secondary:hover:not(:disabled) {
  background: var(--bg-secondary);
}

.aad-download-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  background: white;
  border: 1px solid var(--border-default);
  color: var(--text-base);
}

.aad-download-btn:hover:not(:disabled) {
  background: #f3f4f6;
  border-color: var(--primary);
  color: var(--primary);
}

.aad-download-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* Filters Section */
.aad-filters-section {
  margin-bottom: 20px;
  padding: 12px;
  background: var(--bg-secondary);
  border-radius: 6px;
  border: 1px solid var(--border-subtle);
}

.aad-filters-container {
  display: flex;
  gap: 12px;
  align-items: flex-end;
  flex-wrap: wrap;
}

.aad-filter-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.aad-label {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-muted);
}

.aad-input {
  padding: 6px 10px;
  border: 1px solid var(--border-default);
  border-radius: 4px;
  font-size: 12px;
  background: white;
  transition: all 0.15s ease;
  color: var(--text-base);
}

.aad-input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 2px var(--primary-light);
}

.aad-input[type="date"] {
  width: 140px;
}

/* Stats Cards */
.aad-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 12px;
  margin-bottom: 20px;
}

.aad-stat-card {
  padding: 12px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  transition: all 0.2s ease;
}

.aad-stat-card:hover {
  border-color: var(--border-default);
  box-shadow: var(--shadow-sm);
}

.aad-stat-label {
  font-size: 11px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
  font-weight: 500;
}

.aad-stat-value {
  font-size: 24px;
  font-weight: 600;
  color: var(--primary);
}

.aad-stat-green {
  color: var(--success) !important;
}

.aad-stat-red {
  color: var(--danger) !important;
}

.aad-stat-orange {
  color: var(--warning) !important;
}

/* Search Bar */
.aad-search-bar {
  margin-bottom: 16px;
}

.aad-search {
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--border-default);
  border-radius: 6px;
  font-size: 13px;
}

.aad-search:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 2px var(--primary-light);
}

/* Table */
.aad-table-wrapper {
  border: 1px solid var(--border-default);
  border-radius: 6px;
  overflow: hidden;
  margin-bottom: 16px;
}

.aad-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.aad-table thead {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-default);
}

.aad-table th {
  padding: 10px 12px;
  text-align: left;
  font-weight: 500;
  color: var(--text-muted);
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.aad-col-index {
  width: 50px;
  text-align: center;
}

.aad-table tbody tr {
  border-bottom: 1px solid var(--border-subtle);
  transition: background 0.15s ease;
}

.aad-table tbody tr:hover {
  background: var(--bg-default);
}

.aad-table td {
  padding: 10px 12px;
  color: var(--text-base);
}

.aad-link {
  color: var(--primary);
  text-decoration: none;
  font-weight: 500;
}

.aad-link:hover {
  text-decoration: underline;
}

/* Status Badges */
.aad-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border-radius: 12px;
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  white-space: nowrap;
  border: 1px solid;
}

.aad-badge-green {
  background: #dcfce7;
  color: #15803d;
  border-color: #86efac;
}

.aad-badge-red {
  background: #fee2e2;
  color: #b91c1c;
  border-color: #fca5a5;
}

.aad-badge-orange {
  background: #fef3c7;
  color: #b45309;
  border-color: #fcd34d;
}

.aad-badge-gray {
  background: #f3f4f6;
  color: #4b5563;
  border-color: #d1d5db;
}

.aad-empty-state {
  text-align: center;
  padding: 40px 12px;
  color: var(--text-muted);
}

.aad-empty-state p {
  margin: 0;
  font-size: 12px;
}

/* Loading Spinner */
.aad-spinner {
  display: inline-block;
  width: 16px;
  height: 16px;
  border: 2px solid var(--border-subtle);
  border-top-color: var(--primary);
  border-radius: 50%;
  animation: aad-spin 0.8s linear infinite;
}

@keyframes aad-spin {
  to { 
    transform: rotate(360deg);
  }
}

.aad-loading-row td {
  text-align: center;
  padding: 20px 12px;
}

/* Footer / Pagination */
.aad-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  font-size: 12px;
}

.aad-pagination-info {
  color: var(--text-muted);
}

.aad-pagination-buttons {
  display: flex;
  gap: 6px;
  align-items: center;
}

.aad-page-numbers {
  display: flex;
  gap: 4px;
}

.aad-page-btn {
  min-width: 32px;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 12px;
  border: 1px solid var(--border-default);
  background: white;
  color: var(--text-base);
  cursor: pointer;
  transition: all 0.15s ease;
}

.aad-page-btn:hover:not(.aad-page-active) {
  background: var(--bg-secondary);
}

.aad-page-active {
  background: var(--primary) !important;
  color: white !important;
  border-color: var(--primary) !important;
}

/* Responsive Design */
@media (max-width: 1024px) {
  .aad-stats {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .aad-header {
    flex-direction: column;
  }

  .aad-header-actions {
    width: 100%;
    justify-content: space-between;
  }

  .aad-filters-container {
    flex-direction: column;
  }

  .aad-input[type="date"] {
    width: 100%;
  }

  .aad-stats {
    grid-template-columns: repeat(2, 1fr);
  }

  .aad-footer {
    flex-direction: column;
    align-items: stretch;
  }

  .aad-pagination-buttons {
    justify-content: center;
  }

  .aad-table {
    font-size: 12px;
  }

  .aad-table th,
  .aad-table td {
    padding: 8px 10px;
  }

  .aad-col-index {
    width: 40px;
  }
}

@media (max-width: 480px) {
  .aad-title {
    font-size: 18px;
  }

  .aad-subtitle {
    font-size: 11px;
  }

  .aad-input[type="date"] {
    width: 100%;
  }

  .aad-filters-container {
    flex-direction: column;
  }

  .aad-stats {
    grid-template-columns: 1fr;
  }

  .aad-table {
    font-size: 11px;
  }

  .aad-table th,
  .aad-table td {
    padding: 6px 8px;
  }

  .aad-stat-value {
    font-size: 20px;
  }

  .aad-badge {
    font-size: 10px;
    padding: 2px 6px;
  }

  .aad-header-actions {
    flex-direction: column-reverse;
  }

  .aad-header-actions .aad-btn {
    width: 100%;
    justify-content: center;
  }
}
